do $patch$ declare d text; begin select pg_get_functiondef('public.be_approved_tariff_lookup_key(text)'::regprocedure) into d; if strpos(d,'with aliases(alias,key) as (values ')=0 then raise exception 'Unexpected lookup definition'; end if; d:=replace(d,'with aliases(alias,key) as (values ', 'with aliases(alias,key) as (values (''hlaingtharyar'',''လှိုင်သာယာ''),(''hlaingtharyar(east)'',''လှိုင်သာယာ''),(''hlaingtharyar(west)'',''လှိုင်သာယာ''),(''hlaingtharyareast'',''လှိုင်သာယာ''),(''hlaingtharyarwest'',''လှိုင်သာယာ''),(''hlaingthayareast'',''လှိုင်သာယာ''),(''hlaingthayarwest'',''လှိုင်သာယာ''),(''hlaingtharya(east)'',''လှိုင်သာယာ''),(''hlaingtharya(west)'',''လှိုင်သာယာ''),(''လှိုင်သာယာ(အရှေ့ပိုင်း)'',''လှိုင်သာယာ''),(''လှိုင်သာယာ(အနောက်ပိုင်း)'',''လှိုင်သာယာ''),(''လှိုင်သာယာအရှေ့ပိုင်း'',''လှိုင်သာယာ''),(''လှိုင်သာယာအနောက်ပိုင်း'',''လှိုင်သာယာ''),'); execute d; end $patch$;